61	/**
62	 * @author Vitaliy Fedoriv
63	 */
64	
65	@RestController
66	@CrossOrigin(exposedHeaders = "errors, content-type")
67	@RequestMapping("/api")
68	public class OwnerRestControllerV1 implements OwnersApi {
69	
70	    /**
71	     * Basic syntactic check for an email address: a non-empty local part, an '@', and a domain with
72	     * at least one dot and a two-or-more letter top-level label. Case is ignored here; accepted
73	     * addresses are lower-cased before being stored.
74	     */
75	    private static final Pattern EMAIL_PATTERN =
76	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
77	
78	    /** An owner's postcode, when supplied, must be exactly four digits. */
79	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
80	
81	    /**
82	     * Dedicated logger for audit side-effects. Emitting audit records on a well-known, separately
83	     * named logger keeps them addressable independently of the class's diagnostic logging.
84	     */
85	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
86	
87	    /**
88	     * Maximum number of owners a single city may contain. A create that would take the owner's city
89	     * to more than this many owners - i.e. the city already holds this many - is rejected with a 409.
90	     */
91	    private static final int CITY_OWNER_LIMIT = 50;
92	
93	    /**
94	     * Maximum number of owners that may be registered on a single day. A create that would take the
95	     * number of owners sharing a {@code registrationDate} beyond this many - i.e. that many owners
96	     * have already been created that day - is rejected with a 429.
97	     */
98	    private static final int DAILY_OWNER_LIMIT = 100;
99	
100	    /**
101	     * Number of owners that must already have been created for a given day before the create
102	     * response flags a bulk sign-up. When more than this many owners already share a
103	     * {@code registrationDate}, the response's {@code bulkSignupWarning} is {@code true}.
104	     */
105	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
106	
107	    private final ClinicService clinicService;
108	
109	    private final OwnerMapper ownerMapper;
110	
111	    private final PetMapper petMapper;
112	
113	    private final VisitMapper visitMapper;
114	
115	    public OwnerRestControllerV1(ClinicService clinicService,
116	                                 OwnerMapper ownerMapper,
117	                                 PetMapper petMapper,
118	                                 VisitMapper visitMapper) {
119	        this.clinicService = clinicService;
120	        this.ownerMapper = ownerMapper;
121	        this.petMapper = petMapper;
122	        this.visitMapper = visitMapper;
123	    }
124	
125	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
126	    @Override
127	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
128	        Collection<Owner> owners;
129	        if (lastName != null) {
130	            owners = this.clinicService.findOwnerByLastName(lastName);
131	        } else {
132	            owners = this.clinicService.findAllOwners();
133	        }
134	        if (owners.isEmpty()) {
135	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
136	        }
137	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
138	    }
139	
140	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
141	    @Override
142	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
143	        Owner owner = this.clinicService.findOwnerById(ownerId);
144	        if (owner == null) {
145	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
146	        }
147	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
148	        ownerDto.setBulkSignupWarning(isBulkSignupDay(owner.getRegistrationDate()));
149	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
150	    }
151	
152	    /**
153	     * Determines whether the supplied day currently holds more than {@link #BULK_SIGNUP_WARNING_THRESHOLD}
154	     * owners sharing that {@code registrationDate}, which flags an unusually high volume of same-day
155	     * owner sign-ups.
156	     *
157	     * @param registrationDate the day to inspect, or {@code null}
158	     * @return {@code true} when more than the threshold of owners are registered on that day
159	     */
160	    private boolean isBulkSignupDay(LocalDate registrationDate) {
161	        return registrationDate != null
162	            && countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
163	    }
164	
165	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
166	    @Override
167	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
168	        ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
169	        validateRequiredFields(ownerFieldsDto);
170	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
171	        HttpHeaders headers = new HttpHeaders();
172	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
173	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
174	        owner.setEmail(normalizeEmail(owner.getEmail()));
175	        validateRegistrationDate(owner.getRegistrationDate());
176	        if (owner.getRegistrationDate() == null) {
177	            owner.setRegistrationDate(LocalDate.now());
178	        }
179	        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
180	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
181	        owner.setHouseholdId(HouseholdNormalizer.householdId(owner.getLastName(), owner.getAddress()));
182	        owner.setIdentityKey(buildIdentityKey(owner, sharesHousehold));
183	        rejectDuplicateOwner(owner.getIdentityKey());
184	        Integer possibleDuplicateOf = findPossibleDuplicate(owner);
185	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
186	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
187	        if (countOwnersInCity(owner.getCity()) >= CITY_OWNER_LIMIT) {
188	            throw new OwnerCityFullException(owner.getCity());
189	        }
190	        long ownersRegisteredOnDay = countOwnersRegisteredOn(owner.getRegistrationDate());
191	        if (ownersRegisteredOnDay >= DAILY_OWNER_LIMIT) {
192	            throw new OwnerDailyLimitException(owner.getRegistrationDate());
193	        }
194	        boolean bulkSignupWarning = ownersRegisteredOnDay > BULK_SIGNUP_WARNING_THRESHOLD;
195	        owner.setCustomerCode(buildCustomerCode(owner));
196	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
197	        owner.setHouseholdSize(countHouseholdMembers(owner.getHouseholdId()) + 1);
198	        this.clinicService.saveOwner(owner);
199	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
200	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
201	            MembershipLevel.forOwner(owner));
202	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
203	        ownerDto.setBulkSignupWarning(bulkSignupWarning);
204	        headers.setLocation(UriComponentsBuilder.newInstance()
205	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
206	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
207	    }
208	
209	    /**
210	     * Rejects an owner payload that is missing or blank in any required field. Collects the name of
211	     * every offending field and, if there is at least one, raises a {@link MissingOwnerFieldsException}
212	     * so the client receives a 400 whose {@code errors} array lists each missing field. The address is
213	     * checked in its {@link AddressNormalizer#normalize normalized} form, so a value that is blank only
214	     * after normalization is still rejected.
215	     *
216	     * @param ownerFieldsDto the submitted owner fields
217	     */
218	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
219	        List<String> missingFields = new ArrayList<>();
220	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
221	            missingFields.add("firstName");
222	        }
223	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
224	            missingFields.add("lastName");
225	        }
226	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
227	            missingFields.add("address");
228	        }
229	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
230	            missingFields.add("city");
231	        }
232	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
233	            missingFields.add("telephone");
234	        }
235	        if (!missingFields.isEmpty()) {
236	            throw new MissingOwnerFieldsException(missingFields);
237	        }
238	    }
239	
240	    /**
241	     * Validates an owner's optional postcode. Postcode is optional, so a missing or blank value is
242	     * accepted unchanged. When a value is supplied it must be exactly four digits; and when the owner's
243	     * city maps to a known region the postcode must fall within that region's inclusive range (checked
244	     * via {@link OwnerLocality#postcodeMatchesCity}, which owns the region table). A city with no known
245	     * region accepts any 4-digit postcode. A malformed or out-of-range postcode is rejected with a 400
246	     * whose {@code errors} array lists {@code postcode}.
247	     *
248	     * @param postcode the submitted postcode, or {@code null} when none was supplied
249	     * @param city the owner's city, whose region determines the acceptable postcode range
250	     * @throws InvalidOwnerFieldsException if a supplied postcode is not four digits or is out of range
251	     */
252	    private void validatePostcode(String postcode, String city) {
253	        if (!StringUtils.hasText(postcode)) {
254	            return;
255	        }
256	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
257	            throw new InvalidOwnerFieldsException(List.of("postcode"));
258	        }
259	        if (!OwnerLocality.postcodeMatchesCity(postcode, city)) {
260	            throw new InvalidOwnerFieldsException(List.of("postcode"));
261	        }
262	    }
263	
264	    /**
265	     * Validates an owner's optional registration date. Registration date is optional, so a missing
266	     * value is accepted (the create later defaults it to the server date). When a value is supplied
267	     * it may not lie in the future: a date later than the server's current date is rejected with a
268	     * 400 whose {@code errors} array lists {@code registrationDate}.
269	     *
270	     * @param registrationDate the submitted registration date, or {@code null} when none was supplied
271	     * @throws InvalidOwnerFieldsException if a supplied date is later than the server date
272	     */
273	    private void validateRegistrationDate(LocalDate registrationDate) {
274	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
275	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
276	        }
277	    }
278	
279	    /**
280	     * Rejects a submitted owner whose derived {@code identityKey} exactly matches an existing owner's.
281	     * All duplicate detection is consolidated into this single key, so a collision is reported to the
282	     * client as a 409 Conflict regardless of which field(s) coincide. Because the telephone is part of
283	     * the key, two owners that differ in telephone can never collide even when they share every other
284	     * component (for example two members of the same household).
285	     *
286	     * @param identityKey the derived identity key of the owner about to be created
287	     */
288	    private void rejectDuplicateOwner(String identityKey) {
289	        boolean duplicate = this.clinicService.findAllOwners().stream()
290	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
291	        if (duplicate) {
292	            throw new DuplicateOwnerIdentityException(identityKey);
293	        }
294	    }
295	
296	    /**
297	     * Derives the owner's {@code identityKey}, the single value through which all duplicate detection is
298	     * expressed. The key is {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId},
299	     * where the telephone and email have already been normalized. The household segment carries the
300	     * owner's {@code householdId} only when the owner knowingly belongs to a shared household (the
301	     * request opted in with {@code sharesHousehold}); otherwise it is empty, so an owner is identified
302	     * by telephone and email alone.
303	     *
304	     * @param owner the normalized owner about to be created, with its {@code householdId} already set
305	     * @param sharesHousehold whether the request opted into a shared household
306	     * @return the derived identity key
307	     */
308	    private String buildIdentityKey(Owner owner, boolean sharesHousehold) {
309	        String email = StringUtils.hasText(owner.getEmail()) ? owner.getEmail() : "";
310	        String household = sharesHousehold ? owner.getHouseholdId() : "";
311	        return owner.getTelephone() + "|" + email + "|" + household;
312	    }
313	
314	    /**
315	     * Detects a soft-match duplicate for the owner about to be created. A soft match is an owner that
316	     * is not a hard duplicate (its {@code identityKey} did not collide) but that shares an existing
317	     * owner's {@code lastName} (case-insensitively) and {@code postcode} while having a different
318	     * normalized {@code telephone}. Such an owner is still created, but is flagged as a possible
319	     * duplicate of the matching owner. The comparison only applies when a postcode was supplied, since
320	     * both owners must share one; when several existing owners match, the earliest (lowest id) is used.
321	     *
322	     * @param owner the normalized owner about to be created, with its telephone already normalized
323	     * @return the id of the matching existing owner, or {@code null} when there is no soft match
324	     */
325	    private Integer findPossibleDuplicate(Owner owner) {
326	        if (!StringUtils.hasText(owner.getPostcode())) {
327	            return null;
328	        }
329	        return this.clinicService.findAllOwners().stream()
330	            .filter(existing -> owner.getLastName().equalsIgnoreCase(existing.getLastName()))
331	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
332	            .filter(existing -> !owner.getTelephone().equals(existing.getTelephone()))
333	            .map(Owner::getId)
334	            .filter(id -> id != null)
335	            .min(Integer::compareTo)
336	            .orElse(null);
337	    }
338	
339	    /**
340	     * Normalizes an optional email address for owner creation. Email is optional, so a missing or
341	     * blank value is left untouched. When a value is supplied it must be a syntactically valid
342	     * address; the accepted value is lower-cased before it is stored and returned.
343	     *
344	     * @param email the raw email value submitted by the client, or {@code null}
345	     * @return the lower-cased email, or the original blank/{@code null} value when none was supplied
346	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address
347	     */
348	    private String normalizeEmail(String email) {
349	        if (!StringUtils.hasText(email)) {
350	            return email;
351	        }
352	        if (!EMAIL_PATTERN.matcher(email).matches()) {
353	            throw new InvalidOwnerFieldsException(List.of("email"));
354	        }
355	        return email.toLowerCase();
356	    }
357	
358	    /**
359	     * Assigns the owner's customer code, formatted {@code <REGION>-<HASH8>}. The region is derived
360	     * from the owner's postcode (falling back to its city), and the code itself - region plus the
361	     * hash of the owner's normalized telephone and last name - is composed by {@link CustomerCode}.
362	     *
363	     * @param owner the normalized owner about to be created
364	     * @return the assigned customer code
365	     */
366	    private String buildCustomerCode(Owner owner) {
367	        String region = OwnerLocality.forPostcodeAndCity(owner.getPostcode(), owner.getCity());
368	        return CustomerCode.forRegionAndIdentity(region, owner.getTelephone(), owner.getLastName());
369	    }
370	
371	    /**
372	     * Counts how many owners already exist that share the supplied first and last name, compared
373	     * case-insensitively. This reflects the number of namesakes present <em>before</em> the current
374	     * owner is created and is stored on the new owner as its {@code namesakeCount}.
375	     *
376	     * @param firstName the submitted owner's first name
377	     * @param lastName the submitted owner's last name
378	     * @return the number of existing owners with the same first and last name, ignoring case
379	     */
380	    private int countNamesakes(String firstName, String lastName) {
381	        return (int) this.clinicService.findAllOwners().stream()
382	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
383	                && lastName.equalsIgnoreCase(existing.getLastName()))
384	            .count();
385	    }
386	
387	    /**
388	     * Counts how many existing owners already belong to the supplied household, identified by its
389	     * {@code householdId}. Used when creating an owner to determine the household's size once the new
390	     * owner is added (this count plus one).
391	     *
392	     * @param householdId the normalized household identifier of the owner being created
393	     * @return the number of existing owners already sharing that {@code householdId}
394	     */
395	    private int countHouseholdMembers(String householdId) {
396	        return (int) this.clinicService.findAllOwners().stream()
397	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
398	            .count();
399	    }
400	
401	    /**
402	     * Counts how many owners already live in the supplied city, compared case-insensitively. Used to
403	     * enforce the per-city capacity limit when a new owner is created.
404	     *
405	     * @param city the submitted owner's city
406	     * @return the number of existing owners in that city, ignoring case
407	     */
408	    private long countOwnersInCity(String city) {
409	        return this.clinicService.findAllOwners().stream()
410	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
411	            .count();
412	    }
413	
414	    /**
415	     * Counts how many owners have already been created on the supplied registration date. Used to
416	     * enforce the per-day capacity limit when a new owner is created.
417	     *
418	     * @param registrationDate the registration date of the owner being created
419	     * @return the number of existing owners already registered on that date
420	     */
421	    /**
422	     * Rolls a registration date forward to a business day. A registration date must fall on a
423	     * business day, so when the supplied or defaulted date lands on a Saturday or Sunday it is
424	     * moved forward to the following Monday; a weekday is returned unchanged. Every value derived
425	     * from the registration date (such as the membership number's year segment) and the daily
426	     * create-limit therefore use the adjusted date.
427	     *
428	     * @param date the effective registration date, whether supplied or defaulted to the server date
429	     * @return the same date when it is a weekday, otherwise the next Monday
430	     */
431	    private LocalDate toBusinessDay(LocalDate date) {
432	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
433	            date = date.plusDays(1);
434	        }
435	        return date;
436	    }
437	
438	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
439	        return this.clinicService.findAllOwners().stream()
440	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
441	            .count();
442	    }
443	
444	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
445	    @Override
446	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
447	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
448	        if (currentOwner == null) {
449	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
450	        }
451	        currentOwner.setAddress(ownerFieldsDto.getAddress());
452	        currentOwner.setCity(ownerFieldsDto.getCity());
453	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
454	        currentOwner.setLastName(ownerFieldsDto.getLastName());
455	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
456	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
457	        this.clinicService.saveOwner(currentOwner);
458	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
459	    }
460	
461	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
462	    @Transactional
463	    @Override
464	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
465	        Owner owner = this.clinicService.findOwnerById(ownerId);
466	        if (owner == null) {
467	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
468	        }
469	        this.clinicService.deleteOwner(owner);
470	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
471	    }
472	
473	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
474	    @Override
475	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
476	        Owner owner = this.clinicService.findOwnerById(ownerId);
477	        if (owner == null) {
478	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
479	        }
480	        HttpHeaders headers = new HttpHeaders();
481	        Pet pet = petMapper.toPet(petFieldsDto);
482	        owner.setId(ownerId);
483	        pet.setOwner(owner);
484	        pet.getType().setName(null);
485	        this.clinicService.savePet(pet);
486	        PetDto petDto = petMapper.toPetDto(pet);
487	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
488	            .buildAndExpand(pet.getId()).toUri());
489	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
490	    }
491	
492	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
493	    @Override
494	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
495	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
496	        if (currentOwner != null) {
497	            Pet currentPet = this.clinicService.findPetById(petId);
498	            if (currentPet != null) {
499	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
500	                currentPet.setName(petFieldsDto.getName());
501	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
502	                this.clinicService.savePet(currentPet);
503	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
504	            }
505	        }
506	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
507	    }
508	
509	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
510	    @Override
511	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
512	        HttpHeaders headers = new HttpHeaders();
513	        Visit visit = visitMapper.toVisit(visitFieldsDto);
514	        Pet pet = new Pet();
515	        pet.setId(petId);
516	        visit.setPet(pet);
517	        this.clinicService.saveVisit(visit);
518	        VisitDto visitDto = visitMapper.toVisitDto(visit);
519	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
520	            .buildAndExpand(visit.getId()).toUri());
521	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
522	    }
523	
524	
525	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
526	    @Override
527	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
528	        Owner owner = this.clinicService.findOwnerById(ownerId);
529	        if (owner != null) {
530	            Pet pet = owner.getPet(petId);
531	            if (pet != null) {
532	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
533	            }
534	        }
535	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
536	    }
